{"path":"lib/books.ts","content":"import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: 'reading' | 'finished';
  addedAt: string;
  finishedAt: string | null;
};

const file = path.join(process.cwd(), 'data', 'books.json');
// Serialize writes within this process so two form submissions cannot lose each other.
let pending: Promise<unknown> = Promise.resolve();

export async function getBooks(): Promise<Book[]> {
  try {
    const books: unknown = JSON.parse(await readFile(file, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Invalid books file');
    return books as Book[];
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    throw error;
  }
}

async function saveBooks(books: Book[]) {
  await mkdir(path.dirname(file), { recursive: true });
  const temp = `${file}.${randomUUID()}.tmp`;
  await writeFile(temp, JSON.stringify(books, null, 2) + '\n', 'utf8');
  await rename(temp, file);
}

function serialize<T>(operation: () => Promise<T>): Promise<T> {
  const result = pending.then(operation);
  pending = result.catch(() => {});
  return result;
}

export async function addBook(title: string, author: string, notes: string): Promise<Book> {
  return serialize(async () => {
    const books = await getBooks();
    const book: Book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: 'reading',
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    await saveBooks([book, ...books]);
    return book;
  });
}

export async function finishBook(id: string): Promise<boolean> {
  return serialize(async () => {
    const books = await getBooks();
    const book = books.find((item) => item.id === id);
    if (!book) return false;
    if (book.status === 'finished') return true;
    book.status = 'finished';
    book.finishedAt = new Date().toISOString();
    await saveBooks(books);
    return true;
  });
}
"}

