import { redirect } from 'next/navigation';
import { revalidatePath } from 'next/cache';
import { addBook, finishBook } from '@/lib/books';

export async function createBook(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim();
  const author = String(formData.get('author') ?? '').trim();
  const notes = String(formData.get('notes') ?? '').trim();
  if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
    throw new Error('Please provide a title and author within the allowed lengths.');
  }
  const book = await addBook(title, author, notes);
  revalidatePath('/');
  redirect(`/books/${book.id}`);
}

export async function markFinished(formData: FormData) {
  const id = String(formData.get('id') ?? '');
  if (!/^[0-9a-f-]{36}$/.test(id) || !(await finishBook(id))) {
    throw new Error('Book not found.');
  }
  revalidatePath('/');
  revalidatePath(`/books/${id}`);
  redirect(`/books/${id}`);
}
"}

