  expect(await finishBook('not-a-book')).toBe(false);
  expect((await getBooks()).find(({ id }) => id === first.id)).toMatchObject({ status: 'finished', finishedAt, notes: 'A note' });
  expect(JSON.parse(await readFile(path.join(directory, 'data', 'books.json'), 'utf8'))).toHaveLength(2);
});
"}

